package com.hmdp.ai.runtime.knowledge.chunking;
import com.hmdp.ai.domain.knowledge.ChunkFragment;import com.hmdp.ai.domain.knowledge.ChunkingPolicy;import java.util.*;
final class ChunkingSupport {private ChunkingSupport(){}static List<ChunkFragment>windows(String text,ChunkingPolicy p,Integer page,String section,String heading,Integer start){List<ChunkFragment>out=new ArrayList<>();String value=text==null?"":text.trim();if(value.isEmpty())return out;int offset=0;while(offset<value.length()){int end=Math.min(value.length(),offset+p.getMaxChars());if(end<value.length()){int boundary=Math.max(value.lastIndexOf('。',end),value.lastIndexOf('\n',end));if(boundary>offset+p.getMinChars())end=boundary+1;}String part=value.substring(offset,end).trim();if(!part.isEmpty())out.add(new ChunkFragment(part,page,section,heading,null,null,null,null,null,start==null?null:start+offset,start==null?null:start+end));if(end>=value.length())break;offset=Math.max(offset+1,end-p.getOverlapChars());}return out;}static String headings(List<String> values){return values==null||values.isEmpty()?null:String.join(" / ",values);}}
